        private const BindingFlags Own = BindingFlags.Public | BindingFlags.NonPublic |
            BindingFlags.Instance | BindingFlags.Static | BindingFlags.DeclaredOnly;
        private static int checks;
        private static void Check(bool value, string message) { if (!value) throw new InvalidOperationException(message); checks++; }
        private static FieldInfo Field(Type type, string name)
        {
            while (type != null) { var f = type.GetField(name, Own); if (f != null) return f; type = type.BaseType; }
            throw new MissingFieldException(name);
        }
        private static object Read(object value, string name) => Field(value.GetType(), name).GetValue(value);
        private static void Write(object value, string name, object data) => Field(value.GetType(), name).SetValue(value, data);
        private static object Call(object value, string name, params object[] arguments)
        {
            Type type = value.GetType(); MethodInfo method = null;
            while (type != null && method == null) { method = type.GetMethod(name, Own); type = type.BaseType; }
            if (method == null) throw new MissingMethodException(name);
            try { return method.Invoke(value, arguments); }
            catch (TargetInvocationException error) { System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(error.InnerException).Throw(); throw; }
        }
        private static T Raw<T>() => (T)FormatterServices.GetUninitializedObject(typeof(T));
        private static void Near(float actual, float expected, string message, float tolerance = 1e-5f)
        { Check(Math.Abs(actual - expected) <= tolerance, message + ": " + actual + " expected " + expected); }
        private static void Vector(Vector3 actual, Vector3 expected, string message)
        { Near(actual.x, expected.x, message+" x"); Near(actual.y, expected.y, message+" y"); Near(actual.z, expected.z, message+" z"); }
        private static void Rotation(Quaternion actual, Quaternion expected, string message)
        { Check(Quaternion.Angle(actual, expected) < .04f, message); }
        private static string Canon(Type type)
        {
            if (type.IsGenericParameter) return type.DeclaringMethod == null ? "!" + type.GenericParameterPosition : "!!" + type.GenericParameterPosition;
            if (type.IsByRef) return Canon(type.GetElementType()) + "&";
            if (type.IsGenericType) return type.GetGenericTypeDefinition().FullName + "<" + string.Join(",",type.GetGenericArguments().Select(Canon)) + ">";
            return type.FullName;
        }
